CREATE TABLE schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('Owner','Administrator','Sales','Accounting','Purchasing','Read Only')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE customers(id uuid PRIMARY KEY, company text NOT NULL, contact text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', billing_address text NOT NULL DEFAULT '', shipping_address text NOT NULL DEFAULT '', customer_type text NOT NULL DEFAULT 'Customer', tax_exempt boolean NOT NULL DEFAULT false, pricing_tier text NOT NULL DEFAULT 'Retail', payment_terms text NOT NULL DEFAULT 'Net 30', credit_terms text NOT NULL DEFAULT '', account_status text NOT NULL DEFAULT 'Active', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_contacts(id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), name text NOT NULL, email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '');
CREATE TABLE suppliers(id uuid PRIMARY KEY, name text NOT NULL, contact text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', currency text NOT NULL DEFAULT 'CAD' CHECK(currency IN ('CAD','USD','CNY','EUR')), payment_terms text NOT NULL DEFAULT '', account_number text NOT NULL DEFAULT '', shipping_terms text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products(id uuid PRIMARY KEY, sku text NOT NULL UNIQUE, model text NOT NULL DEFAULT '', name text NOT NULL, brand text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Automatic Door Parts', description text NOT NULL DEFAULT '', cost_cents bigint NOT NULL DEFAULT 0 CHECK(cost_cents>=0), list_price_cents bigint NOT NULL DEFAULT 0 CHECK(list_price_cents>=0), contractor_price_cents bigint NOT NULL DEFAULT 0 CHECK(contractor_price_cents>=0), stock_quantity numeric(12,3) NOT NULL DEFAULT 0 CHECK(stock_quantity>=0), reorder_point numeric(12,3) NOT NULL DEFAULT 0 CHECK(reorder_point>=0), lead_days integer NOT NULL DEFAULT 0 CHECK(lead_days>=0), minimum_quantity numeric(12,3) NOT NULL DEFAULT 1 CHECK(minimum_quantity>0), unit text NOT NULL DEFAULT 'Each', taxable boolean NOT NULL DEFAULT true, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_suppliers(id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), supplier_id uuid NOT NULL REFERENCES suppliers(id), supplier_sku text NOT NULL DEFAULT '', cost_cents bigint NOT NULL CHECK(cost_cents>=0), currency text NOT NULL DEFAULT 'CAD' CHECK(currency IN ('CAD','USD','CNY','EUR')), minimum_quantity numeric(12,3) NOT NULL DEFAULT 1 CHECK(minimum_quantity>0), lead_days integer NOT NULL DEFAULT 0, is_primary boolean NOT NULL DEFAULT false, notes text NOT NULL DEFAULT '', UNIQUE(product_id,supplier_id));
CREATE UNIQUE INDEX one_primary_supplier ON product_suppliers(product_id) WHERE is_primary;
CREATE TABLE product_variants(id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), sku text NOT NULL UNIQUE, options jsonb NOT NULL DEFAULT '{}', cost_cents bigint NOT NULL DEFAULT 0 CHECK(cost_cents>=0), price_cents bigint NOT NULL DEFAULT 0 CHECK(price_cents>=0));
CREATE TABLE product_addons(id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), supplier_id uuid REFERENCES suppliers(id), sku text NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', cost_cents bigint NOT NULL DEFAULT 0 CHECK(cost_cents>=0), price_cents bigint NOT NULL DEFAULT 0 CHECK(price_cents>=0));
CREATE TABLE projects(id uuid PRIMARY KEY, number text NOT NULL UNIQUE, name text NOT NULL, customer_id uuid NOT NULL REFERENCES customers(id), job_site text NOT NULL DEFAULT '', contact text NOT NULL DEFAULT '', customer_po text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Open', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_sequences(kind text NOT NULL, year integer NOT NULL, last_value integer NOT NULL CHECK(last_value>0), PRIMARY KEY(kind,year));
CREATE TABLE documents(id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('estimate','invoice','purchase_order','sales_order')), number text NOT NULL UNIQUE, customer_id uuid REFERENCES customers(id), supplier_id uuid REFERENCES suppliers(id), project_id uuid REFERENCES projects(id), source_id uuid REFERENCES documents(id), status text NOT NULL DEFAULT 'Draft', currency text NOT NULL CHECK(currency IN ('CAD','USD','CNY','EUR')), exchange_rate numeric(12,6) NOT NULL DEFAULT 1 CHECK(exchange_rate>0), party_snapshot jsonb NOT NULL, business_snapshot jsonb NOT NULL, customer_po text NOT NULL DEFAULT '', reference text NOT NULL DEFAULT '', issue_date date NOT NULL, due_date date, ship_to text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', terms text NOT NULL DEFAULT '', subtotal_cents bigint NOT NULL CHECK(subtotal_cents>=0), tax_cents bigint NOT NULL CHECK(tax_cents>=0), total_cents bigint NOT NULL CHECK(total_cents>=0), cost_cents bigint NOT NULL CHECK(cost_cents>=0), revision integer NOT NULL DEFAULT 1, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((kind='purchase_order' AND supplier_id IS NOT NULL) OR (kind<>'purchase_order' AND customer_id IS NOT NULL)));
CREATE UNIQUE INDEX one_conversion ON documents(source_id,kind,supplier_id) WHERE source_id IS NOT NULL AND kind='purchase_order';
CREATE UNIQUE INDEX one_customer_conversion ON documents(source_id,kind) WHERE source_id IS NOT NULL AND kind<>'purchase_order';
CREATE INDEX documents_customer_po ON documents(customer_po);
CREATE TABLE document_lines(id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES documents(id), position integer NOT NULL, product_id uuid REFERENCES products(id), sku text NOT NULL, description text NOT NULL, brand text NOT NULL DEFAULT '', quantity numeric(12,3) NOT NULL CHECK(quantity>0), unit_price_cents bigint NOT NULL CHECK(unit_price_cents>=0), unit_cost_cents bigint NOT NULL CHECK(unit_cost_cents>=0), discount_bps integer NOT NULL DEFAULT 0 CHECK(discount_bps BETWEEN 0 AND 10000), taxes jsonb NOT NULL DEFAULT '[]', line_total_cents bigint NOT NULL CHECK(line_total_cents>=0), tax_cents bigint NOT NULL CHECK(tax_cents>=0), cost_cents bigint NOT NULL CHECK(cost_cents>=0), received_quantity numeric(12,3) NOT NULL DEFAULT 0 CHECK(received_quantity>=0 AND received_quantity<=quantity), shipped_quantity numeric(12,3) NOT NULL DEFAULT 0 CHECK(shipped_quantity>=0 AND shipped_quantity<=quantity));
CREATE TABLE payments(id uuid PRIMARY KEY, invoice_id uuid NOT NULL REFERENCES documents(id), customer_id uuid NOT NULL REFERENCES customers(id), date date NOT NULL, amount_cents bigint NOT NULL CHECK(amount_cents>0), method text NOT NULL, reference text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', idempotency_key text NOT NULL UNIQUE, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_movements(id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), document_id uuid REFERENCES documents(id), quantity numeric(12,3) NOT NULL, reason text NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE email_logs(id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES documents(id), revision integer NOT NULL, recipient text NOT NULL, subject text NOT NULL, status text NOT NULL CHECK(status IN ('Pending','Sent','Failed')), failure_reason text, provider_id text, attempted_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE audit_logs(id bigserial PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, changes jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION protect_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit history is append-only'; END $$;
CREATE TRIGGER audit_no_changes BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION protect_audit();
CREATE TABLE settings(id integer PRIMARY KEY CHECK(id=1), value jsonb NOT NULL);
CREATE TABLE external_mappings(id uuid PRIMARY KEY, provider text NOT NULL, entity_type text NOT NULL, internal_id uuid NOT NULL, external_id text NOT NULL, synchronized_at timestamptz, UNIQUE(provider,entity_type,internal_id), UNIQUE(provider,entity_type,external_id));
INSERT INTO settings(id,value) VALUES(1,'{"business_name":"Elevated Automatic Door Parts","business_address":"","phone":"","email":"","tax_numbers":"","base_currency":"CAD","default_tax":[],"estimate_validity":30,"invoice_due_days":30,"payment_terms":"Net 30","pdf_footer":"Thank you for your business.","ship_to":"","email_templates":{"estimate":{"subject":"Estimate {{number}} — Elevated Automatic Door Parts","body":"Hello {{customer}},\n\nAttached is your estimate {{number}}.\nProject: {{project}}\nTotal: {{total}}\n\nPlease contact us with any questions.\n\nElevated Automatic Door Parts"},"invoice":{"subject":"Invoice {{number}} — Elevated Automatic Door Parts","body":"Hello {{customer}},\n\nAttached is invoice {{number}} for {{total}}.\nThank you for your business.\n\nElevated Automatic Door Parts"},"purchase_order":{"subject":"Purchase order {{number}} — Elevated Automatic Door Parts","body":"Hello {{customer}},\n\nAttached is purchase order {{number}}. Please acknowledge receipt and confirm delivery.\n\nElevated Automatic Door Parts"},"sales_order":{"subject":"Sales order {{number}} — Elevated Automatic Door Parts","body":"Hello {{customer}},\n\nAttached is sales order {{number}}.\n\nElevated Automatic Door Parts"}}}');
INSERT INTO schema_migrations(version) VALUES(1);
